import React, { useEffect, useState } from 'react';
import { motion } from 'framer-motion';
import './UserTable.css';

const UserTable = () => {
  const [codes, setCodes] = useState([]);
  const [searchTerm, setSearchTerm] = useState(''); // State for search input

  useEffect(() => {
    fetch('https://leader-acadmy.hwnix.com/api/code/users')
      .then((response) => response.json())
      .then((data) => {
        console.log(data); // Inspect the structure
        setCodes(data.codes || []); // Set the codes array from the response
      })
      .catch((error) => console.error('Error fetching data:', error));
  }, []);

  const handleResetCode = (code) => {
    fetch(`https://leader-acadmy.hwnix.com/api/reset_code/${code}`, { method: 'Get' })
      .then((response) => response.json())
      .then((data) => {
        console.log(`Code ${code} reset successfully:`, data);
        // Optionally, refetch data or update the UI
      })
      .catch((error) => console.error(`Error resetting code ${code}:`, error));
  };

  // Filtered codes based on search term
  const filteredCodes = codes.filter((code) =>
    code.code.includes(searchTerm) || (code.user && code.user.phone.includes(searchTerm))
  );

  return (
    <motion.div 
      className="table-container"
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{ duration: 0.5 }}
    >
      <h2>User Codes</h2>
      
      {/* Search bar */}
      <input 
        type="text" 
        placeholder="Search by code or phone" 
        value={searchTerm}
        onChange={(e) => setSearchTerm(e.target.value)}
        className="search-input"
      />
      
      {filteredCodes.length > 0 ? (
        <table className="user-table">
          <thead>
            <tr>
              <th>Code</th>
              <th>Name</th>
              <th>Phone</th>
              <th>Reset Code</th>
            </tr>
          </thead>
          <tbody>
            {filteredCodes
              .filter((code) => code.code.length > 8) // Filter codes longer than 8 digits
              .map((code) => (
                <motion.tr 
                  key={code.id} 
                  whileHover={{ scale: 1.05 }}
                  whileTap={{ scale: 0.95 }}
                >
                  <td>{code.code}</td>
                  <td>{code.user ? code.user.name : 'Not used'}</td>
                  <td>{code.user ? code.user.phone : 'Not used'}</td>
                  <td>
                    <button 
                      onClick={() => handleResetCode(code.code)} 
                      className="reset-button"
                    >
                      Reset
                    </button>
                  </td>
                </motion.tr>
              ))}
          </tbody>
        </table>
      ) : (
        <p>No data available.</p>
      )}
    </motion.div>
  );
};

export default UserTable;
